import json, math, sys
from fractions import Fraction as F
MODS=[0.06,0.07,0.08,0.09,0.10,0.11,0.12,0.13,0.14,0.15]
GOING=["barrel_wheel","centre_pinion","centre_wheel","third_pinion","third_wheel","fourth_pinion","fourth_wheel","escape_pinion"]
DIAL=["cannon_pinion","minute_wheel","minute_pinion","hour_wheel"]
ARB={"barrel_wheel":"barrel","centre_pinion":"centre","centre_wheel":"centre","third_pinion":"third","third_wheel":"third",
"fourth_pinion":"fourth","fourth_wheel":"fourth","escape_pinion":"escape","cannon_pinion":"centre","hour_wheel":"centre",
"minute_wheel":"minute","minute_pinion":"minute"}
MESH=[("barrel_wheel","centre_pinion"),("centre_wheel","third_pinion"),("third_wheel","fourth_pinion"),("fourth_wheel","escape_pinion"),
("cannon_pinion","minute_wheel"),("minute_pinion","hour_wheel")]
def validate(inst,d):
    err=[]
    A=dict(inst["fixed_arbors"]); A.update(d["arbors"])
    G=d["gears"]; P=inst["plate_radius"]
    dist=lambda a,b: math.hypot(a[0]-b[0],a[1]-b[1])
    R=lambda g: G[g]["module"]*(G[g]["teeth"]+2)/2
    for g in GOING+DIAL:
        t=G[g]["teeth"]; m=G[g]["module"]
        if not any(abs(m-x)<1e-9 for x in MODS): err.append(("mod",g))
        if g.endswith("pinion"): ok=7<=t<=16
        elif g=="barrel_wheel": ok=40<=t<=140
        else: ok=30<=t<=140
        if not ok: err.append(("teeth",g))
    T=lambda g:G[g]["teeth"]
    fourth=F(T("centre_wheel"),T("third_pinion"))*F(T("third_wheel"),T("fourth_pinion"))
    if fourth!=60: err.append(("fourthrate",fourth))
    esc=fourth*F(T("fourth_wheel"),T("escape_pinion"))
    if esc!=F(inst["beats_per_hour"],30): err.append(("escrate",esc))
    hr=F(T("cannon_pinion"),T("minute_wheel"))*F(T("minute_pinion"),T("hour_wheel"))
    if hr!=F(1,12): err.append(("hour",hr))
    pr=6.5*T("barrel_wheel")/T("centre_pinion")
    if pr<inst["power_reserve_target_h"]: err.append(("pr",pr))
    lv=lambda g: G[g]["level"] if g in GOING else G[g]["dial_level"]
    for a,b in MESH:
        if abs(G[a]["module"]-G[b]["module"])>1e-9: err.append(("meshmod",a))
        if lv(a)!=lv(b): err.append(("meshlvl",a))
        need=G[a]["module"]*(T(a)+T(b))/2
        if abs(dist(A[ARB[a]],A[ARB[b]])-need)>0.005: err.append(("meshdist",a,dist(A[ARB[a]],A[ARB[b]]),need))
    meshset={frozenset(x) for x in MESH}
    # layers
    def layers(g):
        if g in GOING:
            l=G[g]["level"]; return {l,l+1} if g=="barrel_wheel" else {l}
        return {G[g]["dial_level"]}
    for g in GOING:
        if not all(0<=l<=7 for l in layers(g)): err.append(("lvlrange",g))
    for g in DIAL:
        if not 0<=G[g]["dial_level"]<=2: err.append(("dlvl",g))
    el=d["escape_wheel_level"]
    if not 0<=el<=7: err.append("eslvl")
    if el==G["escape_pinion"]["level"]: err.append("esc same")
    items=[(g,A[ARB[g]],R(g),layers(g),"G" if g in GOING else "D") for g in GOING+DIAL]
    items.append(("escape_wheel",A["escape"],inst["escape_wheel"]["radius"],{el},"G"))
    arbof=dict(ARB); arbof["escape_wheel"]="escape"
    for i in range(len(items)):
        for j in range(i+1,len(items)):
            a,b=items[i],items[j]
            if a[4]!=b[4]: continue
            if arbof[a[0]]==arbof[b[0]]:
                if a[3]&b[3]: err.append(("samearb layer",a[0],b[0]))
                continue
            if frozenset((a[0],b[0])) in meshset: continue
            if a[3]&b[3] and dist(a[1],b[1])<a[2]+b[2]+0.10-1e-12: err.append(("overlap",a[0],b[0],dist(a[1],b[1])-a[2]-b[2]))
    for g,c,r,_,k in items:
        if math.hypot(*c)+r>P-0.30+1e-12: err.append(("plate",g))
        if k=="G":
            if dist(c,inst["balance"]["centre"])<r+inst["balance"]["radius"]+0.10: err.append(("balance",g))
            clr=["barrel","centre","third","fourth","escape"]
        else: clr=["centre","minute","fourth"]
        partners={arbof[g]}|{ARB[x] for p in meshset if g in p for x in p}
        for an in clr:
            if an in partners: continue
            if dist(c,A[an])<r+0.25: err.append(("arborclr",g,an))
    names=list(A)
    for n in names:
        if math.hypot(*A[n])>P-1.0: err.append(("arbedge",n))
    for i in range(len(names)):
        for j in range(i+1,len(names)):
            if dist(A[names[i]],A[names[j]])<0.5: err.append(("arbclose",names[i],names[j]))
    gl={l for g in GOING for l in layers(g)}|{el}
    dl={G[g]["dial_level"] for g in DIAL}
    return err,pr,len(gl)+len(dl)
if __name__=="__main__":
    inst=json.load(open(sys.argv[1])); d=json.load(open(sys.argv[2]))
    print(validate(inst,d))
EOF

